$('#modal').addEventListener('cancel',e=>{e.preventDefault();closeModal();});
$('#modal').addEventListener('input',e=>{if(e.target.closest('form')||e.target.matches('textarea'))S.modalDirty=true;});
function checkIdle(){if(!demo&&S.session.loggedIn&&Date.now()-S.lastActivity>1200000){void lockSession('Ordinacija je zaključana posle 20 minuta neaktivnosti. Prijavite se ponovo.');return true;}return false;}
